  "methods": [
    {
      "title": "What this is",
      "text": "A rapid evidence map of 500 concepts, grouped into 20 themes, using 97 selected research and authoritative sources located through 30 September 2026. Each concept has an assessment and a practical application."
    },
    {
      "title": "What this is not",
      "text": "It is not 500 independent systematic reviews, a complete search of every world database, or a survey of PhD opinion. Most broad labels are not standardized interventions."
    },
    {
      "title": "Search approach",
      "text": "Targeted web searches for systematic reviews, meta-analyses, randomized trials, primary research and relevant official guidance. Recent 2024–2026 research was sought alongside older foundational studies and conflicting findings. No preregistered search protocol or exhaustive screening count was used."
    },
    {
      "title": "Source access",
      "text": "Some sources were assessed through abstracts or indexed primary-paper excerpts; accessible full texts were used where available. The Evidence sources sheet records access and a key limitation. No claim of full-text review of every paper is made."
    },
    {
      "title": "Meaning of success",
      "text": "Health and functioning, psychological well-being, learning, relationships, effective goal pursuit and sound use of resources. Evidence for one outcome is not proof of higher income, fame or overall life success."
    },
    {
      "title": "What the rank means",
      "text": "Learning priority, synthesized for a general adult beginner: breadth of likely usefulness, research support and directness, actionability, burden and prerequisite value. It is an editorial judgment, not a calculated scientific league table."
    },
    {
      "title": "How order was made",
      "text": "The 28 foundations were arranged into a practical starting sequence. The remaining concepts are ordered by priority band, then evidence-basis category (synthesis, experiment, observation, mixed, indirect, principle), then original concept ID. Adjacent ranks are not measured differences in benefit."
    },
    {
      "title": "How to interpret lower ranks",
      "text": "Lower priority does not mean worthless. A highly relevant specialist idea can matter more to you than a general foundation. Ethical principles such as consent do not require an outcome trial to be obligatory."
    },
    {
      "title": "Priority 1 — Foundations",
      "text": "Broadly useful starting practices and prerequisites. Includes some practical conventions and ethical requirements with limited direct testing; read the evidence basis separately."
    },
    {
      "title": "Priority 2 — Build next",
      "text": "Useful additions once the basic direction and behavior system are established. Choose what addresses a current need."
    },
    {
      "title": "Priority 3 — Use when relevant",
      "text": "Tools for a particular problem, role or stage of life. Relevance should determine when you explore them."
    },
    {
      "title": "Priority 4 — Explore later",
      "text": "More specialized, abstract or indirectly supported concepts. They can enrich understanding after a practical foundation."
    },
    {
      "title": "Priority 5 — Optional frameworks",
      "text": "Philosophical orientations or frameworks with little direct intervention evidence in this review. This is not a judgment of their moral or spiritual worth."
    },
    {
      "title": "Intervention synthesis (I)",
      "text": "A review of intervention studies supports the linked topic or program. This label describes evidence type, not high confidence. It may be a related component rather than the exact concept; check directness."
    },
    {
      "title": "Specific experiment / trial (R)",
      "text": "One or a limited set of experiments supports a particular intervention or mechanism. Replication, longer follow-up and generalization may remain open."
    },
    {
      "title": "Observational / mechanisms (O)",
      "text": "Associations, longitudinal findings or mechanism research inform the idea. Even prospective associations do not establish that deliberately changing the trait causes the outcome."
    },
    {
      "title": "Mixed or contested (M)",
      "text": "Research is inconsistent, disputed or too methodologically uneven to justify a straightforward positive claim."
    },
    {
      "title": "Indirect application (X)",
      "text": "A reasonable adaptation of related evidence, but the exact practice or label was not directly established in this review. The action is an illustration, not a validated protocol."
    },
    {
      "title": "Principle / framework (P)",
      "text": "A philosophical, ethical, mathematical or practical framework. Contextual references are supplied without implying experimental validation."
    },
    {
      "title": "Direct topic (D)",
      "text": "The cited source examines the named construct or a close operational version. It does not necessarily test the one-line action suggested here."
    },
    {
      "title": "Related component / program (F)",
      "text": "The source concerns a wider program, nearby construct or component. An effect of the package cannot be attributed to this individual ingredient."
    },
    {
      "title": "Context only; no direct test (N)",
      "text": "The reference provides context only. No direct test of the concept or its proposed practice was verified here."
    },
    {
      "title": "No formal certainty score",
      "text": "No independent risk-of-bias assessment, GRADE scoring, pooled effect-size computation or expert consensus exercise was performed. When a source supplies its own certainty rating, it is reported."
    },
    {
      "title": "Shared and overlapping evidence",
      "text": "Many of the 500 concepts overlap. Several rows can cite one review, and reviews can include the same trials. These are not 500 independent discoveries; source counts must not be added as independent participants."
    },
    {
      "title": "Publication year versus study cutoff",
      "text": "A 2026 review can summarize much older studies. Latest linked year is the newest selected contextual source, not proof that the exact concept received a new trial in that year. The official investing resource uses access year."
    },
    {
      "title": "Comparability",
      "text": "Effect sizes from memory tests, symptoms, income and well-being are not interchangeable. Publication bias, inactive comparators and self-report can inflate apparent benefit."
    },
    {
      "title": "Age and cultural relevance",
      "text": "Evidence often comes from students, working adults or clinical samples. Findings do not automatically transfer to a 64-year-old or across cultures. Older-adult studies are identified where available; adjust practices to your capacity and context."
    },
    {
      "title": "What researchers think",
      "text": "The guide reports published findings and disagreements rather than treating credentials as proof. Named researchers are entry points into the literature; they have not endorsed this ranking."
    },
    {
      "title": "Using the guide",
      "text": "Start with one meaningful problem and two or three practices. Read the finding, limitation and source together. Review changes over time. Do not treat a personal before/after improvement as definitive proof of cause."
    },
    {
      "title": "Narrative for everyday readers",
      "text": "Use the sequence: a recognizable situation, a decision, the concept in plain language, the relevant evidence and its limits, then one manageable experiment. Put the lived problem before the technical term."
    }
  ],
